-- Migration 442: AA-1122 (S282, tech lead decision 16/11/2026, items 3-5) — the settings of automatic search demand
-- research, its hard monthly cap and the tour People Also Ask backfill, and the research freshness windows moved to
-- maker-checker at 180 days.
--
-- Why. Research ran only when an administrator called the API, nothing bought data for new places on its own and no
-- monthly cap could be enforced (shared.spend_budget refuses a month cap on non-LLM rows). AA-1122 adds a nightly
-- research tick with per-run and hard monthly caps, a selection order (never researched first, then the oldest), a
-- rolling refresh that spreads expiry over the year, alerts, and a tour PAA backfill. Tech lead S279: every threshold,
-- schedule, cap and window is a setting on Platform › Settings, never a code literal or an env var alone.
--
-- What.
--   1. The seed block (read by scripts/settings/gen_compiled_defaults.py into shared/settings/compiled_defaults.json in
--      this PR): 22 platform keys, each with its plain label and EN + VI operator guide (CIS 416 rule), enforced (the
--      code PR reads them; services/seo_intelligence/research_settings.py names every key in this PR, the settings-lint
--      reader check):
--        area seo:   cis.seo.research_auto_enabled (bool, off, maker_checker), research_auto_window_start_utc (17) /
--                    _end_utc (23), research_auto_new_min_places (20), research_auto_new_max_wait_days (7),
--                    research_auto_refresh_every_days (30, maker_checker), research_refresh_ahead_days (150,
--                    maker_checker), research_refresh_max_share_pct (17 %, maker_checker), research_auto_dfs_queue
--                    (standard | live, standard, maker_checker), research_auto_max_consecutive_failures (2),
--                    research_requalify_max_places (50, maker_checker), research_market_tenant_statuses (list, [active],
--                    maker_checker), research_auto_activation_stale_pct (50 %), research_new_wait_alert_days (14),
--                    research_month_warn_pct (80 %), tour_paa_max (10), tour_paa_per_keyword (5)
--        area spend: cis.spend.research_auto_max_usd_per_run (3 USD, maker_checker), research_max_usd_per_month
--                    (5 USD, maker_checker; 0 = no research spend, never unlimited), research_auto_min_run_usd
--                    (0.05 USD), research_jev_ask_estimate_usd (0.002 USD), tour_paa_backfill_max_usd_per_run (1 USD,
--                    maker_checker)
--   2. The edit block (an UPDATE of existing rows, CIS 424 pattern): cis.seo.research_volume_fresh_days and
--      cis.seo.research_serp_fresh_days (CIS 434) get approval maker_checker (they decide what research buys again) and
--      the default 180 days (tech lead: refresh window 90-180 days); bounds unchanged (30-730); their guides say so.
--   3. A post-check: every seed and edit row is in force.
--   4. Register 442.
--
-- Behaviour on apply. None for running code until the code PR: no value row is seeded and nothing on main reads the new
-- keys. The two edited windows: main reads them already, so their new default (180 days, was 365) applies from the deploy
-- that carries the regenerated compiled_defaults.json (this PR) when no value row is set: places researched more than
-- 180 days ago become stale for the next manual run (on 16/11/2026 the oldest research row is from September 2026, so
-- none is). A value an administrator already set keeps winning.
--
-- Class: CONTRACT (root ADR 0017 decision 3; no migrate directive line): config rows INSERTed into and UPDATEd in an
-- existing table, and a DO block. MIG-4: a migration-only PR (with 440 and 441), applied on Dev by Infra Migration
-- Apply when every job table is idle (ADR 0017a), then the code PR (no readiness raise: a reader falls back to the
-- compiled defaults). DM-6.1: no personal data. DM-7.1: no new table.
--
-- Number. Follows 441 (this lane: 440-442). If the owner main max + 1 differs at merge, renumber (git grep '442_' and
-- '442' here, in tests/integration/test_aa1122_migrations_440_442.py, compiled_defaults.json's _generated line and
-- docs/implementation-notes/AA-1122.md).
--
-- Locks. INSERT of 22 rows and UPDATE of 2 rows of a small table read by no hot path (the reader reads
-- shared.setting_value); the definition guard trigger (CIS 407) allows the file's role, cis_owner. lock_timeout 5s.
-- Idempotent (ON CONFLICT (key) DO NOTHING; the UPDATE skips equal rows), one transaction, self-registering.
--
-- Rollback (a new forward migration, after the code PR is reverted): DELETE the new keys' value rows first, then the
-- keys; put the two windows back to single approval and 365 days.

BEGIN;
SET LOCAL lock_timeout = '5s';

-- settings-seed:begin (scripts/settings/gen_compiled_defaults.py reads the JSON array of the dollar-quoted seed)
INSERT INTO shared.setting_definition
    (key, app, area, label, description, value_type, unit, min_value, max_value, allowed_values, default_value,
     scope_kind, impact, approval, evidence_required, env_override, cache_s, enforced, guide)
SELECT s.key, s.app, s.area, s.label, s.description, s.value_type, s.unit, s.min_value, s.max_value, s.allowed_values,
       s.default_value, s.scope_kind, s.impact, s.approval, s.evidence_required, s.env_override, s.cache_s, s.enforced,
       s.guide
  FROM jsonb_to_recordset($seed$
[
{"key": "cis.seo.research_auto_enabled", "app": "cis", "area": "seo", "label": "Automatic research: on", "description": "On: the worker's nightly research tick buys search demand data for new places and refreshes the oldest places on its own, inside the per-run and monthly caps (cis.spend.research_auto_max_usd_per_run, cis.spend.research_max_usd_per_month). Off (default): research runs only when an administrator clicks Run on the Research tab. Read by services/acp_contract/research_auto.py (the nightly research tick).", "value_type": "bool", "unit": null, "min_value": null, "max_value": null, "allowed_values": null, "default_value": false, "scope_kind": "platform", "impact": "high", "approval": "maker_checker", "evidence_required": false, "env_override": null, "cache_s": 60, "enforced": true, "guide": {"en": {"what": "Whether the platform buys keyword data for new and ageing places by itself every night, within the caps.", "raise": "On: new tours get search demand within days without anyone clicking; spend stays inside the monthly cap.", "lower": "Off: nothing is bought until an administrator runs research by hand on the Research tab.", "when": "Turn it on once the caps are set and a preview looks right; turn it off to stop all automatic spend at once.", "example": "With the default off, nothing is bought until an administrator clicks Run; switched on, at most 3 USD a night and 5 USD a month."}, "vi": {"what": "Có cho nền tảng tự mua dữ liệu từ khoá cho địa điểm mới và địa điểm sắp cũ mỗi đêm, trong giới hạn trần hay không.", "raise": "Bật: tour mới có dữ liệu nhu cầu tìm kiếm sau vài ngày mà không cần ai bấm; chi tiêu vẫn nằm trong trần tháng.", "lower": "Tắt: không mua gì cho tới khi quản trị viên tự chạy research ở tab Research.", "when": "Bật khi đã đặt trần và bản xem trước hợp lý; tắt để dừng ngay mọi chi tiêu tự động.", "example": "Với mặc định tắt, không mua gì cho tới khi quản trị viên bấm Run; khi bật, tối đa 3 USD một đêm và 5 USD một tháng."}}},
{"key": "cis.seo.research_auto_window_start_utc", "app": "cis", "area": "seo", "label": "Automatic research: night window start (UTC hour)", "description": "The first UTC hour in which the nightly research tick may enqueue a run (a run blocks backend deploys while it works, DM-11.4). With the end hour it forms [start, end). Read by services/acp_contract/research_auto.py (the nightly research tick).", "value_type": "int", "unit": "hour (UTC)", "min_value": 0, "max_value": 23, "allowed_values": null, "default_value": 17, "scope_kind": "platform", "impact": "low", "approval": "single", "evidence_required": false, "env_override": null, "cache_s": 60, "enforced": true, "guide": {"en": {"what": "The first hour (UTC) of the night window in which automatic research may start.", "raise": "Runs start later in the night.", "lower": "Runs may start earlier, closer to working hours.", "when": "Move the window when deploys or other night jobs collide with research.", "example": "With the default 17, runs may start from 17:00 UTC (00:00 in Vietnam)."}, "vi": {"what": "Giờ đầu tiên (UTC) của khung đêm mà research tự động được phép bắt đầu.", "raise": "Lần chạy bắt đầu muộn hơn trong đêm.", "lower": "Lần chạy có thể bắt đầu sớm hơn, gần giờ làm việc hơn.", "when": "Dời khung giờ khi deploy hoặc job đêm khác va chạm với research.", "example": "Với mặc định 17, lần chạy được bắt đầu từ 17:00 UTC (00:00 giờ Việt Nam)."}}},
{"key": "cis.seo.research_auto_window_end_utc", "app": "cis", "area": "seo", "label": "Automatic research: night window end (UTC hour)", "description": "The UTC hour at which the nightly research window closes (exclusive). No run is enqueued at or after it. Read by services/acp_contract/research_auto.py (the nightly research tick).", "value_type": "int", "unit": "hour (UTC)", "min_value": 1, "max_value": 24, "allowed_values": null, "default_value": 23, "scope_kind": "platform", "impact": "low", "approval": "single", "evidence_required": false, "env_override": null, "cache_s": 60, "enforced": true, "guide": {"en": {"what": "The hour (UTC) at which the night window for automatic research closes.", "raise": "Runs may still start later in the night.", "lower": "The window closes earlier.", "when": "Shorten it when morning deploys wait for a research run to finish.", "example": "With the default 23, no run starts at 23:00 UTC or later."}, "vi": {"what": "Giờ (UTC) đóng khung đêm của research tự động.", "raise": "Lần chạy vẫn có thể bắt đầu muộn hơn trong đêm.", "lower": "Khung giờ đóng sớm hơn.", "when": "Rút ngắn khi deploy buổi sáng phải chờ một lần research chạy xong.", "example": "Với mặc định 23, không lần chạy nào bắt đầu từ 23:00 UTC trở đi."}}},
{"key": "cis.seo.research_auto_new_min_places", "app": "cis", "area": "seo", "label": "Automatic research: new places that start a run", "description": "A 'new places' run starts when at least this many places in scope were never researched (no segment_research_log row). Read by services/acp_contract/research_auto.py (the nightly research tick).", "value_type": "int", "unit": "places", "min_value": 1, "max_value": 5000, "allowed_values": null, "default_value": 20, "scope_kind": "platform", "impact": "medium", "approval": "single", "evidence_required": false, "env_override": null, "cache_s": 60, "enforced": true, "guide": {"en": {"what": "How many never-researched places must be waiting before automatic research buys them in one run.", "raise": "Fewer, larger runs; a new place may wait longer (up to the maximum wait).", "lower": "More, smaller runs; new places get data sooner.", "when": "Raise it when nightly runs buy only a handful of places each; lower it when new tours need demand faster.", "example": "With the default 20, the run starts the night 20 new places are waiting."}, "vi": {"what": "Cần bao nhiêu địa điểm chưa từng nghiên cứu đang chờ thì research tự động mới mua trong một lần chạy.", "raise": "Ít lần chạy hơn nhưng lớn hơn; địa điểm mới có thể chờ lâu hơn (tới thời gian chờ tối đa).", "lower": "Nhiều lần chạy nhỏ hơn; địa điểm mới có dữ liệu sớm hơn.", "when": "Tăng khi mỗi lần chạy đêm chỉ mua vài địa điểm; giảm khi tour mới cần dữ liệu nhu cầu nhanh hơn.", "example": "Với mặc định 20, lần chạy bắt đầu vào đêm có 20 địa điểm mới đang chờ."}}},
{"key": "cis.seo.research_auto_new_max_wait_days", "app": "cis", "area": "seo", "label": "Automatic research: longest wait of a new place", "description": "A 'new places' run also starts when the oldest never-researched place has waited this many days since its first atom, even below the minimum count. Read by services/acp_contract/research_auto.py (the nightly research tick).", "value_type": "int", "unit": "days", "min_value": 1, "max_value": 60, "allowed_values": null, "default_value": 7, "scope_kind": "platform", "impact": "medium", "approval": "single", "evidence_required": false, "env_override": null, "cache_s": 60, "enforced": true, "guide": {"en": {"what": "The longest a new place waits for its search demand data before a run buys it anyway.", "raise": "New places may wait longer when few arrive.", "lower": "New places get data sooner, in smaller runs.", "when": "Lower it when a new tour must show demand within days.", "example": "With the default 7 days, one new place alone is bought a week after its tour was atomized."}, "vi": {"what": "Thời gian lâu nhất một địa điểm mới chờ dữ liệu nhu cầu trước khi một lần chạy vẫn mua nó.", "raise": "Địa điểm mới có thể chờ lâu hơn khi ít địa điểm mới.", "lower": "Địa điểm mới có dữ liệu sớm hơn, trong các lần chạy nhỏ hơn.", "when": "Giảm khi tour mới phải có nhu cầu tìm kiếm trong vài ngày.", "example": "Với mặc định 7 ngày, một địa điểm mới đơn lẻ được mua một tuần sau khi tour của nó được atomize."}}},
{"key": "cis.seo.research_auto_refresh_every_days", "app": "cis", "area": "seo", "label": "Automatic research: days between refresh runs", "description": "A rolling refresh run (stale places first, then a share of the places that will go stale soon) starts when the last automatic refresh run, of any outcome, was created more than this many days ago. Read by services/acp_contract/research_auto.py (the nightly research tick).", "value_type": "int", "unit": "days", "min_value": 7, "max_value": 120, "allowed_values": null, "default_value": 30, "scope_kind": "platform", "impact": "medium", "approval": "maker_checker", "evidence_required": false, "env_override": null, "cache_s": 60, "enforced": true, "guide": {"en": {"what": "How often automatic research re-buys ageing places, so their data never expires all at once.", "raise": "Refresh runs are rarer; more places can go stale between them.", "lower": "Refresh runs are more frequent and smaller.", "when": "Keep about a month; lower it only if many places go stale between runs.", "example": "With the default 30 days, one refresh run a month."}, "vi": {"what": "Bao lâu research tự động mua lại các địa điểm sắp cũ một lần, để dữ liệu không hết hạn cùng lúc.", "raise": "Lần làm mới thưa hơn; nhiều địa điểm có thể cũ giữa hai lần.", "lower": "Lần làm mới dày hơn và nhỏ hơn.", "when": "Giữ khoảng một tháng; chỉ giảm khi nhiều địa điểm bị cũ giữa các lần chạy.", "example": "Với mặc định 30 ngày, mỗi tháng một lần làm mới."}}},
{"key": "cis.seo.research_refresh_ahead_days", "app": "cis", "area": "seo", "label": "Automatic research: refresh ahead of expiry (days)", "description": "A refresh run also buys places whose research will go stale within this many days (their windows narrowed by it), at most cis.seo.research_refresh_max_share_pct of the scope per run, oldest first, so a block bought in one week does not expire in one week. Never more than the freshness window minus one day. Read by services/acp_contract/research_auto.py (the nightly research tick).", "value_type": "int", "unit": "days", "min_value": 0, "max_value": 365, "allowed_values": null, "default_value": 150, "scope_kind": "platform", "impact": "medium", "approval": "maker_checker", "evidence_required": false, "env_override": null, "cache_s": 60, "enforced": true, "guide": {"en": {"what": "How far ahead of expiry a refresh run may re-buy a place, to spread re-purchases over the months.", "raise": "More places qualify for an early refresh; spend is spread more evenly.", "lower": "Only places close to expiry are bought early; more expire together.", "when": "Keep it a little under the freshness window; 0 turns early refresh off.", "example": "With a 180-day window and the default 150, a place researched 30 days ago may be refreshed early."}, "vi": {"what": "Một lần làm mới được mua lại một địa điểm sớm bao nhiêu ngày trước khi nó hết hạn, để rải việc mua lại qua các tháng.", "raise": "Nhiều địa điểm đủ điều kiện làm mới sớm hơn; chi tiêu được rải đều hơn.", "lower": "Chỉ địa điểm gần hết hạn mới được mua sớm; nhiều địa điểm hết hạn cùng lúc hơn.", "when": "Giữ thấp hơn cửa sổ tươi một chút; 0 là tắt làm mới sớm.", "example": "Với cửa sổ 180 ngày và mặc định 150, địa điểm nghiên cứu 30 ngày trước có thể được làm mới sớm."}}},
{"key": "cis.seo.research_refresh_max_share_pct", "app": "cis", "area": "seo", "label": "Automatic research: early refresh share per run", "description": "The most places one refresh run may buy ahead of expiry, in percent of the places in scope (stale places are not limited by it, only by the caps). Read by services/acp_contract/research_auto.py (the nightly research tick).", "value_type": "pct", "unit": "%", "min_value": 0, "max_value": 100, "allowed_values": null, "default_value": 17, "scope_kind": "platform", "impact": "medium", "approval": "maker_checker", "evidence_required": false, "env_override": null, "cache_s": 60, "enforced": true, "guide": {"en": {"what": "The share of all places one refresh run may buy before they go stale.", "raise": "Early refresh catches up faster and costs more per run.", "lower": "Early refresh is spread over more months.", "when": "About 100 divided by the months of the window spreads expiry evenly (17 % for six months).", "example": "With the default 17 % and 6,000 places, at most about 1,000 places are refreshed early per run."}, "vi": {"what": "Tỷ lệ trên tổng số địa điểm mà một lần làm mới được mua trước khi chúng cũ.", "raise": "Làm mới sớm bắt kịp nhanh hơn và tốn hơn mỗi lần chạy.", "lower": "Làm mới sớm được rải qua nhiều tháng hơn.", "when": "Khoảng 100 chia cho số tháng của cửa sổ thì rải đều (17 % cho sáu tháng).", "example": "Với mặc định 17 % và 6.000 địa điểm, mỗi lần chạy làm mới sớm tối đa khoảng 1.000 địa điểm."}}},
{"key": "cis.seo.research_auto_dfs_queue", "app": "cis", "area": "seo", "label": "Automatic research: DataForSEO endpoint", "description": "The DataForSEO endpoint automatic runs buy through: standard (the Standard queue, about half the price, answers within minutes) or live. Manual runs choose their own. Read by services/acp_contract/research_auto.py (the nightly research tick).", "value_type": "enum", "unit": null, "min_value": null, "max_value": null, "allowed_values": ["standard", "live"], "default_value": "standard", "scope_kind": "platform", "impact": "high", "approval": "maker_checker", "evidence_required": false, "env_override": null, "cache_s": 60, "enforced": true, "guide": {"en": {"what": "Which DataForSEO endpoint automatic research buys through.", "raise": "live (the dearer choice): answers at once, at about twice the price per task.", "lower": "standard (the cheaper choice): answers within minutes in the DataForSEO queue.", "when": "Keep standard: night runs do not need live answers, and live costs about twice as much.", "example": "With the default standard, a 1,000-keyword volume task costs about 0.06 USD."}, "vi": {"what": "Research tự động mua qua endpoint DataForSEO nào.", "raise": "live (lựa chọn đắt hơn): trả lời ngay, giá mỗi task gấp khoảng hai lần.", "lower": "standard (lựa chọn rẻ hơn): trả lời trong vài phút qua hàng đợi DataForSEO.", "when": "Giữ standard: lần chạy đêm không cần trả lời tức thì, còn live đắt gấp khoảng hai lần.", "example": "Với mặc định standard, một task lượng tìm kiếm 1.000 từ khoá tốn khoảng 0,06 USD."}}},
{"key": "cis.seo.research_auto_max_consecutive_failures", "app": "cis", "area": "seo", "label": "Automatic research: failed runs before it pauses", "description": "After this many automatic research runs in a row failed or stopped at a budget, the nightly tick stops enqueueing and alerts (research_auto_failed) until an administrator runs research by hand and it succeeds. Read by services/acp_contract/research_auto.py (the nightly research tick).", "value_type": "int", "unit": "runs", "min_value": 1, "max_value": 10, "allowed_values": null, "default_value": 2, "scope_kind": "platform", "impact": "medium", "approval": "single", "evidence_required": false, "env_override": null, "cache_s": 60, "enforced": true, "guide": {"en": {"what": "How many automatic runs in a row may fail before automatic research pauses itself.", "raise": "A broken run is retried more nights before it pauses (each can spend up to its cap).", "lower": "Automatic research pauses sooner after a failure.", "when": "Keep it low: a run that fails after spending would otherwise spend again every night.", "example": "With the default 2, two failed nights pause it until a manual run succeeds."}, "vi": {"what": "Bao nhiêu lần chạy tự động thất bại liên tiếp thì research tự động tự dừng.", "raise": "Lần chạy lỗi được thử lại thêm nhiều đêm trước khi dừng (mỗi lần có thể chi tới trần).", "lower": "Research tự động dừng sớm hơn sau lỗi.", "when": "Giữ thấp: lần chạy lỗi sau khi đã chi tiền sẽ lại chi mỗi đêm.", "example": "Với mặc định 2, hai đêm lỗi liên tiếp làm nó dừng tới khi một lần chạy tay thành công."}}},
{"key": "cis.seo.research_requalify_max_places", "app": "cis", "area": "seo", "label": "Research: places whose keyword map is rebuilt per run", "description": "The most fresh places one research run re-proposes because the keyword rules would change their stored map (segment_research_batch.needs_requalify). They come after new and stale places; the rest wait for the next run and show on the Research tab. 0 = never in a run. Read by services/acp_contract/segment_research.py.", "value_type": "int", "unit": "places", "min_value": 0, "max_value": 5000, "allowed_values": null, "default_value": 50, "scope_kind": "platform", "impact": "medium", "approval": "maker_checker", "evidence_required": false, "env_override": null, "cache_s": 60, "enforced": true, "guide": {"en": {"what": "How many still-fresh places with an outdated keyword map one run may rebuild (their new keywords are bought in every market).", "raise": "Outdated maps are rebuilt faster; a run can spend more on them.", "lower": "Rebuilds are spread over more runs.", "when": "Raise it after a keyword rule change once a preview shows the cost.", "example": "With the default 50, a run rebuilds at most 50 such places after the new and stale ones."}, "vi": {"what": "Một lần chạy được dựng lại bản đồ từ khoá cho tối đa bao nhiêu địa điểm còn tươi nhưng bản đồ đã lỗi thời (từ khoá mới được mua ở mọi thị trường).", "raise": "Bản đồ lỗi thời được dựng lại nhanh hơn; một lần chạy có thể chi nhiều hơn cho chúng.", "lower": "Việc dựng lại được rải qua nhiều lần chạy hơn.", "when": "Tăng sau khi đổi luật từ khoá, khi bản xem trước đã cho thấy chi phí.", "example": "Với mặc định 50, mỗi lần chạy dựng lại tối đa 50 địa điểm như vậy, sau địa điểm mới và địa điểm cũ."}}},
{"key": "cis.seo.research_market_tenant_statuses", "app": "cis", "area": "seo", "label": "Automatic research: agency statuses whose markets count", "description": "Automatic research buys only the markets declared by active agencies (shared.tenants kind 'agency', is_active, not cancelled) whose account_status is in this list, plus the platform default market. Demo, internal and listed-out agencies never start a purchase. Read by services/acp_contract/research_auto.py (the nightly research tick) and the Research tab.", "value_type": "list", "unit": null, "min_value": null, "max_value": null, "allowed_values": ["lead", "applied", "trial", "active", "past_due", "suspended", "offboarding", "closed"], "default_value": ["active"], "scope_kind": "platform", "impact": "high", "approval": "maker_checker", "evidence_required": false, "env_override": null, "cache_s": 60, "enforced": true, "guide": {"en": {"what": "Which agency account states make their target markets part of automatic research.", "raise": "Adding a state buys the markets of more agencies (trial ones, for example), at a higher monthly cost.", "lower": "Removing a state stops buying the markets only those agencies use; the data already bought stays.", "when": "Add trial when trial agencies should see their own market's demand; keep demo tenants out.", "example": "With the default (active), only paying agencies' markets are bought, plus the platform default."}, "vi": {"what": "Trạng thái tài khoản đại lý nào thì thị trường mục tiêu của đại lý được đưa vào research tự động.", "raise": "Thêm một trạng thái thì mua thị trường của nhiều đại lý hơn (ví dụ đại lý dùng thử), chi phí tháng cao hơn.", "lower": "Bớt một trạng thái thì ngừng mua thị trường chỉ những đại lý đó dùng; dữ liệu đã mua vẫn giữ.", "when": "Thêm trial khi đại lý dùng thử cần thấy nhu cầu của thị trường mình; không đưa tenant demo vào.", "example": "Với mặc định (active), chỉ mua thị trường của đại lý trả tiền, cộng thị trường mặc định của nền tảng."}}},
{"key": "cis.seo.research_auto_activation_stale_pct", "app": "cis", "area": "seo", "label": "Automatic research: share that marks a new market", "description": "A targeted market with more than this percent of the scope stale is a new market (a first purchase of about 1 USD for every place): automatic runs leave it out and the Research tab shows it with its preview price for an administrator's Run. Read by services/acp_contract/research_auto.py (the nightly research tick).", "value_type": "pct", "unit": "%", "min_value": 10, "max_value": 100, "allowed_values": null, "default_value": 50, "scope_kind": "platform", "impact": "medium", "approval": "single", "evidence_required": false, "env_override": null, "cache_s": 60, "enforced": true, "guide": {"en": {"what": "When a market counts as new: then automatic research does not buy it, an administrator decides.", "raise": "More markets are bought automatically, including large first purchases.", "lower": "Large first purchases always wait for an administrator.", "when": "Keep it so a new agency market never starts a large automatic purchase.", "example": "With the default 50 %, a market where half the places were never researched waits for a manual run."}, "vi": {"what": "Khi nào một thị trường được coi là mới: khi đó research tự động không mua, quản trị viên quyết định.", "raise": "Nhiều thị trường được mua tự động hơn, kể cả các lần mua đầu lớn.", "lower": "Các lần mua đầu lớn luôn chờ quản trị viên.", "when": "Giữ để thị trường mới của một đại lý không bao giờ kích hoạt một lần mua tự động lớn.", "example": "Với mặc định 50 %, thị trường có một nửa số địa điểm chưa từng nghiên cứu sẽ chờ một lần chạy tay."}}},
{"key": "cis.seo.research_new_wait_alert_days", "app": "cis", "area": "seo", "label": "Automatic research: alert when a new place waits", "description": "The research_new_waiting alert (admin bell and one e-mail a day) fires when the oldest never-researched place has waited longer than this many days. Read by services/acp_contract/research_auto.py (the nightly research tick).", "value_type": "int", "unit": "days", "min_value": 1, "max_value": 90, "allowed_values": null, "default_value": 14, "scope_kind": "platform", "impact": "low", "approval": "single", "evidence_required": false, "env_override": null, "cache_s": 60, "enforced": true, "guide": {"en": {"what": "How long a new place may wait for search demand data before the team is alerted.", "raise": "Fewer alerts; a stuck new place is noticed later.", "lower": "A stuck new place is noticed sooner.", "when": "Keep it above the longest wait of a new place so the alert means something is stuck.", "example": "With the default 14 days, a place waiting two weeks rings the bell."}, "vi": {"what": "Một địa điểm mới được chờ dữ liệu nhu cầu bao lâu trước khi nhóm nhận cảnh báo.", "raise": "Ít cảnh báo hơn; địa điểm mới bị kẹt được phát hiện muộn hơn.", "lower": "Địa điểm mới bị kẹt được phát hiện sớm hơn.", "when": "Giữ cao hơn thời gian chờ tối đa của địa điểm mới để cảnh báo nghĩa là có gì đó bị kẹt.", "example": "Với mặc định 14 ngày, địa điểm chờ hai tuần sẽ làm chuông báo."}}},
{"key": "cis.seo.research_month_warn_pct", "app": "cis", "area": "seo", "label": "Research: month spend warning", "description": "The research_month_spend alert fires when the month's research spend (DataForSEO + LLM + Jev of every research job, manual and automatic) reaches this percent of cis.spend.research_max_usd_per_month. Read by services/acp_contract/research_auto.py (the nightly research tick).", "value_type": "pct", "unit": "%", "min_value": 10, "max_value": 100, "allowed_values": null, "default_value": 80, "scope_kind": "platform", "impact": "low", "approval": "single", "evidence_required": false, "env_override": null, "cache_s": 60, "enforced": true, "guide": {"en": {"what": "At what share of the monthly research cap the team is warned.", "raise": "The warning comes later, close to the hard stop.", "lower": "The warning comes earlier in the month.", "when": "Keep it below 100 so the warning comes before research stops for the month.", "example": "With the default 80 % of 5 USD, the warning fires at 4 USD."}, "vi": {"what": "Ở mức bao nhiêu phần trăm trần research tháng thì nhóm được cảnh báo.", "raise": "Cảnh báo tới muộn hơn, gần lúc dừng cứng.", "lower": "Cảnh báo tới sớm hơn trong tháng.", "when": "Giữ dưới 100 để cảnh báo tới trước khi research dừng cho tháng.", "example": "Với mặc định 80 % của 5 USD, cảnh báo ở mức 4 USD."}}},
{"key": "cis.seo.tour_paa_max", "app": "cis", "area": "seo", "label": "Tour questions: most questions per tour", "description": "The most People Also Ask questions the tour PAA backfill writes to one tour (silver_aa_internal.seo_context), and the S1 prefetch takes from the research store. Read by services/seo_intelligence/tour_paa.py and s1_prefetch.cached_ideas.", "value_type": "int", "unit": "questions", "min_value": 1, "max_value": 30, "allowed_values": null, "default_value": 10, "scope_kind": "platform", "impact": "low", "approval": "single", "evidence_required": false, "env_override": null, "cache_s": 60, "enforced": true, "guide": {"en": {"what": "How many 'people also ask' questions a tour keeps for its writers.", "raise": "Writers get more questions to answer; prompts get longer.", "lower": "Fewer, more focused questions.", "when": "Change it with the writers' prompt length in mind.", "example": "With the default 10, a tour keeps its 10 first questions."}, "vi": {"what": "Một tour giữ bao nhiêu câu hỏi 'người dùng cũng hỏi' cho người viết.", "raise": "Người viết có nhiều câu hỏi hơn để trả lời; prompt dài hơn.", "lower": "Ít câu hỏi hơn, tập trung hơn.", "when": "Đổi khi đã tính tới độ dài prompt của người viết.", "example": "Với mặc định 10, một tour giữ 10 câu hỏi đầu tiên."}}},
{"key": "cis.seo.tour_paa_per_keyword", "app": "cis", "area": "seo", "label": "Tour questions: questions taken per keyword", "description": "The most questions the tour PAA backfill and the S1 prefetch take from one research keyword before moving to the next keyword of the tour's places, so one place does not fill the list. Read by services/seo_intelligence/tour_paa.py and s1_prefetch.cached_ideas.", "value_type": "int", "unit": "questions", "min_value": 1, "max_value": 10, "allowed_values": null, "default_value": 5, "scope_kind": "platform", "impact": "low", "approval": "single", "evidence_required": false, "env_override": null, "cache_s": 60, "enforced": true, "guide": {"en": {"what": "How many questions one keyword may contribute to a tour's list.", "raise": "One popular place can fill most of the list.", "lower": "Questions come from more places of the tour.", "when": "Lower it for tours that visit many places.", "example": "With the default 5, a tour's 10 questions come from at least two keywords."}, "vi": {"what": "Một từ khoá được góp tối đa bao nhiêu câu hỏi vào danh sách của một tour.", "raise": "Một địa điểm nổi tiếng có thể chiếm phần lớn danh sách.", "lower": "Câu hỏi đến từ nhiều địa điểm của tour hơn.", "when": "Giảm cho các tour đi qua nhiều địa điểm.", "example": "Với mặc định 5, 10 câu hỏi của một tour đến từ ít nhất hai từ khoá."}}},
{"key": "cis.spend.research_auto_max_usd_per_run", "app": "cis", "area": "spend", "label": "Automatic research: spend per run", "description": "The most one automatic research run may spend (DataForSEO + LLM + Jev together), also across its retries: a retry subtracts what earlier attempts of the same job already spent. Never above cis.spend.segment_research_max_usd_per_run nor the month left. Read by services/acp_contract/research_auto.py (the nightly research tick) and the segment_research job.", "value_type": "usd", "unit": "USD/run", "min_value": 0.1, "max_value": 50, "allowed_values": null, "default_value": 3, "scope_kind": "platform", "impact": "high", "approval": "maker_checker", "evidence_required": false, "env_override": null, "cache_s": 60, "enforced": true, "guide": {"en": {"what": "The most one automatic research run may spend, retries included.", "raise": "A run buys more places at once.", "lower": "Each night buys less; large backlogs take more nights.", "when": "Raise it for one month when a new market or a large batch of tours must be bought.", "example": "With the default 3 USD, a night run stops before it spends 3 USD."}, "vi": {"what": "Số tiền tối đa một lần research tự động được chi, tính cả các lần thử lại.", "raise": "Một lần chạy mua được nhiều địa điểm hơn.", "lower": "Mỗi đêm mua ít hơn; tồn đọng lớn cần nhiều đêm hơn.", "when": "Tăng trong một tháng khi phải mua một thị trường mới hoặc một lô tour lớn.", "example": "Với mặc định 3 USD, lần chạy đêm dừng trước khi chi tới 3 USD."}}},
{"key": "cis.spend.research_max_usd_per_month", "app": "cis", "area": "spend", "label": "Research: hard monthly cap", "description": "The most every research job together (segment_research and tour_paa_backfill, manual and automatic) may spend in one UTC calendar month on DataForSEO, the LLM and Jev, measured from the ledger by job (shared.dfs_call_log + shared.llm_call_log joined to shared.job). Refused up front by the Run routes and the nightly tick, and checked before every paid post. 0 = no research spend at all (not unlimited). S1 prefetch and other DataForSEO spend are outside it. Read by shared/cost_guard.py.", "value_type": "usd", "unit": "USD/month", "min_value": 0, "max_value": 100, "allowed_values": null, "default_value": 5, "scope_kind": "platform", "impact": "high", "approval": "maker_checker", "evidence_required": false, "env_override": null, "cache_s": 60, "enforced": true, "guide": {"en": {"what": "The hard monthly limit on research spend (keyword data, the keyword LLM and Jev), manual and automatic runs together.", "raise": "More research can be bought in the month.", "lower": "Research stops earlier in the month; 0 stops all research spend.", "when": "Raise it for one month to activate a new market; the per-tour keyword fetch of the Master rewrite is not inside this cap.", "example": "With the default 5 USD, the run that would pass 5 USD in November stops before that call."}, "vi": {"what": "Trần cứng mỗi tháng cho chi tiêu research (dữ liệu từ khoá, LLM từ khoá và Jev), gộp lần chạy tay và tự động.", "raise": "Mua được nhiều research hơn trong tháng.", "lower": "Research dừng sớm hơn trong tháng; 0 là dừng mọi chi tiêu research.", "when": "Tăng trong một tháng để mở một thị trường mới; phần lấy từ khoá theo tour khi viết lại bản Master không nằm trong trần này.", "example": "Với mặc định 5 USD, lần chạy sắp vượt 5 USD trong tháng 11 sẽ dừng trước lời gọi đó."}}},
{"key": "cis.spend.research_auto_min_run_usd", "app": "cis", "area": "spend", "label": "Automatic research: smallest run worth starting", "description": "When the money left for an automatic run (the smaller of the run cap and the month left) is below this, the nightly tick does not enqueue and raises research_auto_capped. Read by services/acp_contract/research_auto.py (the nightly research tick).", "value_type": "usd", "unit": "USD", "min_value": 0, "max_value": 5, "allowed_values": null, "default_value": 0.05, "scope_kind": "platform", "impact": "low", "approval": "single", "evidence_required": false, "env_override": null, "cache_s": 60, "enforced": true, "guide": {"en": {"what": "The least money left for which an automatic run is still started.", "raise": "Runs near the end of the month's money are skipped.", "lower": "Even tiny runs start.", "when": "Keep it above the price of one volume task.", "example": "With the default 0.05 USD and 0.03 USD left in the month, no run starts and the bell rings."}, "vi": {"what": "Số tiền còn lại tối thiểu để vẫn bắt đầu một lần chạy tự động.", "raise": "Các lần chạy khi tiền trong tháng gần hết bị bỏ qua.", "lower": "Kể cả lần chạy rất nhỏ cũng bắt đầu.", "when": "Giữ cao hơn giá một task lượng tìm kiếm.", "example": "Với mặc định 0,05 USD và còn 0,03 USD trong tháng, không lần chạy nào bắt đầu và chuông báo."}}},
{"key": "cis.spend.research_jev_ask_estimate_usd", "app": "cis", "area": "spend", "label": "Research: reserved price of one Jev keyword check", "description": "Before research asks Jev about its proposed keywords it reserves this much per question against the monthly and run caps, then charges what Jev really cost. Read by services/acp_contract/segment_research_batch.py.", "value_type": "usd", "unit": "USD/question", "min_value": 0.0001, "max_value": 0.1, "allowed_values": null, "default_value": 0.002, "scope_kind": "platform", "impact": "low", "approval": "single", "evidence_required": false, "env_override": null, "cache_s": 60, "enforced": true, "guide": {"en": {"what": "The worst-case price research reserves for one Jev keyword question before asking it.", "raise": "Caps stop research a little earlier.", "lower": "Caps can be passed by a little more if Jev is dearer.", "when": "Keep it at or above the real price per question on the Jev spend page.", "example": "With the default 0.002 USD, 60 questions reserve 0.12 USD."}, "vi": {"what": "Giá xấu nhất research giữ chỗ cho một câu hỏi Jev về từ khoá trước khi hỏi.", "raise": "Trần làm research dừng sớm hơn một chút.", "lower": "Trần có thể bị vượt thêm một chút nếu Jev đắt hơn.", "when": "Giữ bằng hoặc cao hơn giá thật mỗi câu hỏi trên trang chi phí Jev.", "example": "Với mặc định 0,002 USD, 60 câu hỏi giữ chỗ 0,12 USD."}}},
{"key": "cis.spend.tour_paa_backfill_max_usd_per_run", "app": "cis", "area": "spend", "label": "Tour questions: SERP spend per backfill run", "description": "The most one tour PAA backfill run may spend on SERPs for the tours the research store cannot fill (one SERP per tour keyword, through the research cache), inside the monthly research cap. 0 = store only, never buy. Read by services/seo_intelligence/tour_paa.py.", "value_type": "usd", "unit": "USD/run", "min_value": 0, "max_value": 10, "allowed_values": null, "default_value": 1, "scope_kind": "platform", "impact": "medium", "approval": "maker_checker", "evidence_required": false, "env_override": null, "cache_s": 60, "enforced": true, "guide": {"en": {"what": "The most one backfill run of tour questions may spend on search results pages.", "raise": "More tours with no stored question get one bought.", "lower": "Fewer are bought; 0 fills from stored data only.", "when": "Preview first: it shows how many tours the store fills free and the price of the rest.", "example": "With the default 1 USD, about 400 tours can be bought on the live endpoint."}, "vi": {"what": "Số tiền tối đa một lần bổ sung câu hỏi tour được chi cho trang kết quả tìm kiếm.", "raise": "Nhiều tour không có câu hỏi trong kho được mua hơn.", "lower": "Ít được mua hơn; 0 chỉ lấy từ dữ liệu đã có.", "when": "Xem trước: bản xem trước cho biết kho lấp miễn phí bao nhiêu tour và giá của phần còn lại.", "example": "Với mặc định 1 USD, mua được khoảng 400 tour ở endpoint live."}}}
]
$seed$::jsonb) AS s (key text, app text, area text, label text, description text, value_type text, unit text,
                      min_value numeric, max_value numeric, allowed_values jsonb, default_value jsonb, scope_kind text,
                      impact text, approval text, evidence_required boolean, env_override text, cache_s integer,
                      enforced boolean, guide jsonb)
ON CONFLICT (key) DO NOTHING;
-- settings-seed:end

-- settings-edit:begin (scripts/settings/gen_compiled_defaults.py reads the JSON array of the dollar-quoted block)
CREATE TEMP TABLE IF NOT EXISTS m452_edit (key text PRIMARY KEY, doc jsonb NOT NULL) ON COMMIT DROP;
INSERT INTO m452_edit (key, doc)
SELECT e.doc ->> 'key', e.doc
  FROM jsonb_array_elements($edit$[
{"key": "cis.seo.research_volume_fresh_days", "default_value": 180, "approval": "maker_checker", "guide": {"en": {"what": "How long a monthly search volume bought from DataForSEO for a keyword in one market is reused before research buys it again. Each purchase also keeps the 12 monthly values (acp_contract.search_volume_monthly), so the season survives a refresh.", "raise": "Fewer volumes are bought again, so research costs less; demand numbers can be older.", "lower": "Volumes are refreshed more often, so research costs more; demand numbers are newer.", "when": "Keep it between 90 and 180 days (tech lead, 16/11/2026); the automatic refresh spreads the re-purchases over the months.", "example": "With the default of 180 days, a volume bought on 9 November is reused until 8 May."}, "vi": {"what": "Lượng tìm kiếm hằng tháng của một từ khoá ở một thị trường, mua từ DataForSEO, được dùng lại bao lâu trước khi research mua lại. Mỗi lần mua cũng giữ 12 giá trị theo tháng (acp_contract.search_volume_monthly), nên mùa vụ không mất khi làm mới.", "raise": "Ít lượng tìm kiếm bị mua lại hơn nên research rẻ hơn; số nhu cầu có thể cũ hơn.", "lower": "Lượng tìm kiếm được làm mới thường hơn nên research tốn hơn; số nhu cầu mới hơn.", "when": "Giữ trong khoảng 90 đến 180 ngày (tech lead, 16/11/2026); làm mới tự động rải việc mua lại qua các tháng.", "example": "Với mặc định 180 ngày, lượng tìm kiếm mua ngày 9/11 được dùng lại tới ngày 8/5."}}},
{"key": "cis.seo.research_serp_fresh_days", "default_value": 180, "approval": "maker_checker", "guide": {"en": {"what": "How long the search results page bought for a keyword (the questions people also ask, related searches and the sites that rank) is reused before research buys it again. Tour questions filled from the store are refreshed on the same window.", "raise": "Fewer pages are bought again, so research costs less; the questions can be older.", "lower": "Pages are refreshed more often, so research costs more; blogs get newer questions.", "when": "Keep it between 90 and 180 days (tech lead, 16/11/2026); lower it when reviewers find the questions in blogs out of date.", "example": "With the default of 180 days, a results page bought on 9 November is reused until 8 May."}, "vi": {"what": "Trang kết quả tìm kiếm mua cho một từ khoá (các câu hỏi người dùng cũng hỏi, tìm kiếm liên quan và các trang đang xếp hạng) được dùng lại bao lâu trước khi research mua lại. Câu hỏi tour lấy từ kho được làm mới theo cùng cửa sổ.", "raise": "Ít trang bị mua lại hơn nên research rẻ hơn; câu hỏi có thể cũ hơn.", "lower": "Trang được làm mới thường hơn nên research tốn hơn; blog có câu hỏi mới hơn.", "when": "Giữ trong khoảng 90 đến 180 ngày (tech lead, 16/11/2026); giảm khi người duyệt thấy câu hỏi trong blog đã lỗi thời.", "example": "Với mặc định 180 ngày, trang kết quả mua ngày 9/11 được dùng lại tới ngày 8/5."}}}
]$edit$::jsonb) AS e (doc)
ON CONFLICT (key) DO UPDATE SET doc = EXCLUDED.doc;
-- settings-edit:end

UPDATE shared.setting_definition AS d
   SET default_value = COALESCE(e.doc -> 'default_value', d.default_value),
       approval      = COALESCE(e.doc ->> 'approval', d.approval),
       guide         = CASE WHEN e.doc ? 'guide' THEN e.doc -> 'guide' ELSE d.guide END
  FROM m452_edit AS e
 WHERE d.key = e.key
   AND (d.default_value IS DISTINCT FROM COALESCE(e.doc -> 'default_value', d.default_value)
        OR d.approval IS DISTINCT FROM COALESCE(e.doc ->> 'approval', d.approval)
        OR d.guide IS DISTINCT FROM CASE WHEN e.doc ? 'guide' THEN e.doc -> 'guide' ELSE d.guide END);

-- Post-check: four sample keys of the 22 seeded exist, and every edit row is in force (a misspelt key would fail silently otherwise).
DO $check$
DECLARE
    missing text;
    seeded integer;
BEGIN
    SELECT count(*) INTO seeded FROM shared.setting_definition
     WHERE key IN ('cis.seo.research_auto_enabled', 'cis.spend.research_max_usd_per_month',
                   'cis.spend.research_auto_max_usd_per_run', 'cis.spend.tour_paa_backfill_max_usd_per_run');
    IF seeded <> 4 THEN
        RAISE EXCEPTION 'CIS 442: the research settings were not seeded (% of 4 sample keys)', seeded;
    END IF;
    SELECT string_agg(e.key, ', ' ORDER BY e.key) INTO missing
      FROM m452_edit AS e
     WHERE NOT EXISTS (
           SELECT 1 FROM shared.setting_definition AS d
            WHERE d.key = e.key
              AND (NOT e.doc ? 'default_value' OR d.default_value = e.doc -> 'default_value')
              AND (NOT e.doc ? 'approval' OR d.approval = e.doc ->> 'approval')
              AND (NOT e.doc ? 'guide' OR d.guide = e.doc -> 'guide'));
    IF missing IS NOT NULL THEN
        RAISE EXCEPTION 'CIS 442: no definition or not edited: %', missing;
    END IF;
END
$check$;

INSERT INTO shared.schema_versions (version, applied_at, description)
VALUES ('442', now(), 'AA-1122: automatic research, monthly research cap and tour PAA backfill settings')
ON CONFLICT (version) DO NOTHING;

COMMIT;
